mapper.update:
UPDATE conversation_member
SET last_read_seq = LEAST(GREATEST(#{requestedSeq}, last_read_seq), #{maxSeq}),
    updated_at = #{now}
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND deleted = 0
  AND last_read_seq < LEAST(GREATEST(#{requestedSeq}, last_read_seq), #{maxSeq})

UPDATE conversation_member
SET inbox_visible = 0,
    last_read_seq = GREATEST(last_read_seq, #{lastSeq}),
    updated_at = #{now}
WHERE id = #{memberId}
  AND deleted = 0
  AND inbox_visible = 1

  AND (last_message_id = #{lastMessageId,jdbcType=VARCHAR}
       OR (last_message_id IS NULL AND #{lastMessageId,jdbcType=VARCHAR} IS NULL))
